content.content:
.plan {
  position: relative;
  padding: var(--space-5);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-lg);
  background: var(--color-surface);
}

.plan-featured {
  border: 2px solid var(--color-brand);
  box-shadow: var(--shadow-md);
}

.plan-ribbon {
  position: absolute;
  top: -13px;
  left: 50%;
  z-index: 1;
  padding: 3px 12px;
  border-radius: var(--radius-pill);
  background: var(--color-brand);
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  transform: translateX(-50%);
}

.plan-price {
  margin: var(--space-3) 0;
  font-size: 40px;
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.plan-price small {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0;
  color: var(--color-muted);
}

.plan-features {
  margin: var(--space-4) 0 var(--space-5);
